# 선형 스캔 레지스터 할당 — 값마다 살아 있는 구간(시작, 끝)을 보고 레지스터 k 개에 나눠 담는다
intervals = {"a": (0, 9), "b": (1, 3), "c": (2, 8), "d": (4, 6), "e": (5, 9)}

def linear_scan(iv, regs):
    free, active, where = list(regs), [], {}
    for v, (s, e) in sorted(iv.items(), key=lambda x: x[1][0]):
        for w in [w for w in active if iv[w][1] < s]:   # 끝난 값의 레지스터를 돌려받는다
            active.remove(w); free.append(where[w])
        if free:
            where[v] = free.pop(0); active.append(v)
        else:                                             # 모자라면 가장 늦게 끝나는 값을 메모리로(spill)
            far = max(active, key=lambda w: iv[w][1])
            if iv[far][1] > e:
                where[v] = where[far]; where[far] = "stack"; active.remove(far); active.append(v)
            else:
                where[v] = "stack"
    return where

for k in (3, 2):
    print(f"레지스터 {k}개:", linear_scan(intervals, [f"x{10+i}" for i in range(k)]))

# 출력
# 레지스터 3개: {'a': 'x10', 'b': 'x11', 'c': 'x12', 'd': 'x11', 'e': 'stack'}
# 레지스터 2개: {'a': 'stack', 'b': 'x11', 'c': 'x10', 'd': 'x11', 'e': 'stack'}

# 아주 작은 컴파일러: 식 → 파싱(AST) → 3주소 IR → 상수 접기 + 죽은 코드 지우기 → RISC-V 어셈블리
import re

src = "t = 4 * 8; u = x + t; v = 2 + 3; y = u * 1"

def parse(stmt):
    lhs, rhs = [s.strip() for s in stmt.split("=")]
    toks = re.findall(r"\w+|[+*]", rhs)
    if len(toks) == 1:
        return (lhs, "mov", toks[0], None)
    a, op, b = toks
    return (lhs, op, a, b)

ir = [parse(s) for s in src.split(";")]
print("IR(처음):")
for d, op, a, b in ir:
    print(f"  {d} = {a} {op} {b}" if b else f"  {d} = {a}")

# 1) 상수 접기 + 대수 단순화(x*1 → x)
consts, out = {}, []
def val(v): return str(consts.get(v, v))
for d, op, a, b in ir:
    a, b = val(a), (val(b) if b else None)
    if b and a.isdigit() and b.isdigit():
        consts[d] = eval(f"{a}{op}{b}"); continue
    if op == "*" and b == "1":
        out.append((d, "mov", a, None)); continue
    out.append((d, op, a, b))

# 2) 죽은 코드 지우기 — 결과 y 에 닿지 않는 줄을 뒤에서부터 지운다
live, kept = {"y"}, []
for d, op, a, b in reversed(out):
    if d in live:
        kept.append((d, op, a, b)); live |= {a, b} - {None}
kept.reverse()
print("IR(최적화 뒤):")
for d, op, a, b in kept:
    print(f"  {d} = {a} {op} {b}" if b else f"  {d} = {a}")

# 3) 코드 생성 — 변수마다 레지스터 하나(실제는 레지스터 할당이 정한다)
reg = {"x": "a0"}; nxt = iter(["t0", "t1", "t2"])
asm = []
for d, op, a, b in kept:
    rd = reg.setdefault(d, next(nxt))
    ra = reg.get(a, a)
    if op == "mov":
        asm.append(f"mv   {rd}, {ra}")
    elif b.isdigit():
        asm.append(f"addi {rd}, {ra}, {b}" if op == "+" else f"li t6, {b}\nmul  {rd}, {ra}, t6")
    else:
        asm.append(f"{'add' if op == '+' else 'mul'}  {rd}, {ra}, {reg[b]}")
print("RISC-V:")
for line in asm:
    for l in line.split("\n"):
        print("  " + l)

# 출력
# IR(처음):
#   t = 4 * 8
#   u = x + t
#   v = 2 + 3
#   y = u * 1
# IR(최적화 뒤):
#   u = x + 32
#   y = u
# RISC-V:
#   addi t0, a0, 32
#   mv   t1, t0
